import { getFileCategory } from '@mintlify/common';
import fse from 'fs-extra';
import { join } from 'path';
vi.mock('../constants.js', async (importOriginal) => {
    const actual = await importOriginal();
    const { mkdtempSync } = await import('fs');
    const { tmpdir } = await import('os');
    const path = await import('path');
    const root = mkdtempSync(path.join(tmpdir(), 'packages-island-errors-'));
    return {
        ...actual,
        CMD_EXEC_PATH: path.join(root, 'docs'),
        PREVIEW_PATH: path.join(root, 'preview'),
        NEXT_PROPS_PATH: path.join(root, 'props'),
    };
});
vi.mock('../local-preview/listener/regenerateAllSnippets.js', () => ({
    regenerateAllSnippets: vi.fn().mockResolvedValue([]),
}));
vi.mock('@mintlify/package-builder', async (importOriginal) => {
    const actual = await importOriginal();
    const build = async () => ({
        ok: true,
        manifest: {
            version: 1,
            builderVersion: 'test',
            buildId: 'b',
            depsHash: 'd',
            islandsHash: 'i',
            react: { version: '18.3.1', domVersion: '18.3.1' },
            packages: {},
            css: [],
            islands: {},
            files: [],
            diagnostics: [],
        },
        localFiles: [],
        missingLocalFiles: [],
        stats: {},
    });
    return { ...actual, build };
});
import { CMD_EXEC_PATH } from '../constants.js';
import { notifyPackageInputChange, startPackagesDev } from '../local-preview/packages/index.js';
import { clearErrorLogs, getCurrentErrorLogs, setLoggingCallbacks } from '../logging-state.js';
const BROKEN = 'import { LineChart } from "recharts";\n\n<LineChart onClick={() => {}} />\n';
const FIXED = 'import { LineChart } from "recharts";\n\n<LineChart width={400} />\n';
const errorMessages = () => getCurrentErrorLogs().map((log) => log.props.message);
const islandErrorCount = () => errorMessages().filter((message) => /^npm packages: bad\.mdx:3 /.test(message)).length;
const packageErrors = () => errorMessages().filter((message) => message.startsWith('npm packages:'));
const save = async (filename, content) => {
    clearErrorLogs();
    if (content !== undefined)
        await fse.outputFile(join(CMD_EXEC_PATH, filename), content);
    await notifyPackageInputChange(filename, getFileCategory(filename));
};
describe('npm package island errors in the mint dev log', () => {
    beforeAll(() => {
        setLoggingCallbacks(() => { }, () => { }, () => { });
    });
    beforeEach(async () => {
        await fse.emptyDir(CMD_EXEC_PATH);
        await fse.outputJson(join(CMD_EXEC_PATH, 'docs.json'), { name: 'Docs', packages: {} });
        await fse.outputJson(join(CMD_EXEC_PATH, 'package.json'), {
            dependencies: { recharts: '2.15.4' },
        });
        await fse.outputFile(join(CMD_EXEC_PATH, 'bad.mdx'), BROKEN);
        await fse.outputFile(join(CMD_EXEC_PATH, 'other.mdx'), '# Other\n');
        await fse.outputFile(join(CMD_EXEC_PATH, 'styles.css'), 'a{}');
        clearErrorLogs();
        await startPackagesDev();
        expect(islandErrorCount()).toBe(1);
    });
    afterEach(async () => {
        await fse.remove(join(CMD_EXEC_PATH, 'docs.json'));
        await startPackagesDev();
        clearErrorLogs();
    });
    it('keeps them after another page is saved, without repeating them', async () => {
        await save('other.mdx', '# Other edited\n');
        expect(islandErrorCount()).toBe(1);
        await notifyPackageInputChange('other.mdx', 'page');
        expect(islandErrorCount()).toBe(1);
        await save('other.mdx', '# Other edited again\n');
        expect(islandErrorCount()).toBe(1);
    });
    it('keeps them after a file that is not a page is saved', async () => {
        await save('styles.css', 'b{}');
        expect(islandErrorCount()).toBe(1);
    });
    it('keeps them next to the config error while docs.json does not parse', async () => {
        await save('docs.json', '{ "name": "Docs", "packages": {');
        expect(errorMessages()).toContainEqual(expect.stringMatching(/^npm packages: docs\.json could not be loaded/));
        expect(islandErrorCount()).toBe(1);
    });
    it('drops them once the island is fixed and shows them again when it breaks the same way', async () => {
        await save('bad.mdx', FIXED);
        expect(errorMessages()).toEqual([]);
        await save('bad.mdx', BROKEN);
        expect(islandErrorCount()).toBe(1);
    });
    it('drops them when the island is fixed while another page saves at the same time', async () => {
        clearErrorLogs();
        await fse.outputFile(join(CMD_EXEC_PATH, 'bad.mdx'), FIXED);
        await fse.outputFile(join(CMD_EXEC_PATH, 'other.mdx'), '# Other edited\n');
        await Promise.all([
            notifyPackageInputChange('other.mdx', 'page'),
            notifyPackageInputChange('bad.mdx', 'page'),
        ]);
        expect(errorMessages()).toEqual([]);
    });
    it('drops them when the island is fixed while a stylesheet saves at the same time', async () => {
        clearErrorLogs();
        await fse.outputFile(join(CMD_EXEC_PATH, 'bad.mdx'), FIXED);
        await Promise.all([
            notifyPackageInputChange('bad.mdx', 'page'),
            notifyPackageInputChange('styles.css', getFileCategory('styles.css')),
        ]);
        expect(errorMessages()).toEqual([]);
    });
    it('replaces them when a broken page is deleted', async () => {
        await save('worse.mdx', BROKEN);
        expect(packageErrors()).toHaveLength(2);
        await fse.remove(join(CMD_EXEC_PATH, 'bad.mdx'));
        await notifyPackageInputChange('bad.mdx', 'page');
        expect(packageErrors()).toEqual([expect.stringMatching(/^npm packages: worse\.mdx:3 /)]);
    });
});
